{
  "name": "opencode-schedule-center",
  "version": "0.2.2",
  "description": "Scheduled tasks dashboard for OpenCode: create, pause, resume and delete automations with countdowns and cron previews.",
  "type": "module",
  "license": "MIT",
  "author": "meiyx7",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/meiyx7/opencode-schedule-center.git"
  },
  "homepage": "https://github.com/meiyx7/opencode-schedule-center#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "schedule",
    "cron",
    "timer",
    "automation"
  ],
  "exports": {
    "./gui-experimental": "./dist/gui-experimental.cjs",
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "src",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@opencode/client": "2.4.2",
    "@opencode/plugin": "2.4.2"
  },
  "peerDependencies": {
    "effect": "^4.1.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "effect": "4.1.0",
    "esbuild": "^0.28.2",
    "solid-js": "^1.9.5",
    "typescript": "^5.7.0",
    "vite": "^7.1.0",
    "vite-plugin-solid": "^2.11.0"
  },
  "scripts": {
    "build": "vite build",
    "dev": "vite build --watch",
    "typecheck": "tsc --noEmit",
    "test": "esbuild src/store.ts src/scan-coordinator.ts src/gui/format.ts --format=esm --platform=node --outdir=test/.build --log-level=warning && node --test test/*.test.mjs",
    "prepublishOnly": "node scripts/ensure-ci-publish.mjs && npm run build"
  }
}
